-- Feral 42430 / native scenario 1108: real chest loot and final-stage admission.
-- Data only; keeps the original native 214714 scene/equip/credit and outro actor chain.
SET @feral_concat := @@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
DROP TEMPORARY TABLE IF EXISTS feral_pickup_expected;
CREATE TEMPORARY TABLE feral_pickup_expected LIKE conditions;
INSERT INTO feral_pickup_expected
(SourceTypeOrReferenceId,SourceGroup,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition,ErrorTextId,ScriptName,Comment)
SELECT scope.kind,scope.grp,scope.entry,scope.source,variant.grp,
 IF(rule.kind=0,variant.quest,rule.kind),0,rule.value1,
 IF(rule.kind=44,variant.stage,IF(rule.kind=2,1,0)),
 IF(rule.kind=2 AND scope.kind=4,1,0),IF(rule.kind=2 AND scope.kind=4,1,rule.negative),
 0,'','Feral: native Fangs loot and owned final-stage presentation'
FROM (SELECT 4 kind,250386 grp,128860 entry,0 source
 UNION ALL SELECT 22,1,250386,1 UNION ALL SELECT 22,3,250386,1) scope
CROSS JOIN (SELECT 0 grp,6 stage,9 quest UNION ALL SELECT 1,6,28
 UNION ALL SELECT 2,7,9 UNION ALL SELECT 3,7,28) variant
CROSS JOIN (SELECT 2 kind,128860 value1,0 negative UNION ALL SELECT 15,1024,0
 UNION ALL SELECT 22,1612,0 UNION ALL SELECT 44,1108,0 UNION ALL SELECT 0,42430,0
 UNION ALL SELECT 8,42430,1 UNION ALL SELECT 36,0,0) rule
WHERE scope.kind=22 OR variant.stage=6;
START TRANSACTION;
SET @feral_safe := (SELECT COUNT(*) FROM gameobject_template WHERE entry=250386 AND Data1 IN(0,250386))=1
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entry` AS CHAR),'NULL'),COALESCE(CAST(`type` AS CHAR),'NULL'),COALESCE(CAST(`displayId` AS CHAR),'NULL'),COALESCE(CAST(`name` AS CHAR),'NULL'),COALESCE(CAST(`IconName` AS CHAR),'NULL'),COALESCE(CAST(`castBarCaption` AS CHAR),'NULL'),COALESCE(CAST(`unk1` AS CHAR),'NULL'),COALESCE(CAST(`faction` AS CHAR),'NULL'),COALESCE(CAST(`flags` AS CHAR),'NULL'),COALESCE(CAST(`size` AS CHAR),'NULL'),COALESCE(CAST(`questItem1` AS CHAR),'NULL'),COALESCE(CAST(`questItem2` AS CHAR),'NULL'),COALESCE(CAST(`questItem3` AS CHAR),'NULL'),COALESCE(CAST(`questItem4` AS CHAR),'NULL'),COALESCE(CAST(`questItem5` AS CHAR),'NULL'),COALESCE(CAST(`questItem6` AS CHAR),'NULL'),COALESCE(CAST(`Data0` AS CHAR),'NULL'),'0',COALESCE(CAST(`Data2` AS CHAR),'NULL'),COALESCE(CAST(`Data3` AS CHAR),'NULL'),COALESCE(CAST(`Data4` AS CHAR),'NULL'),COALESCE(CAST(`Data5` AS CHAR),'NULL'),COALESCE(CAST(`Data6` AS CHAR),'NULL'),COALESCE(CAST(`Data7` AS CHAR),'NULL'),COALESCE(CAST(`Data8` AS CHAR),'NULL'),COALESCE(CAST(`Data9` AS CHAR),'NULL'),COALESCE(CAST(`Data10` AS CHAR),'NULL'),COALESCE(CAST(`Data11` AS CHAR),'NULL'),COALESCE(CAST(`Data12` AS CHAR),'NULL'),COALESCE(CAST(`Data13` AS CHAR),'NULL'),COALESCE(CAST(`Data14` AS CHAR),'NULL'),COALESCE(CAST(`Data15` AS CHAR),'NULL'),COALESCE(CAST(`Data16` AS CHAR),'NULL'),COALESCE(CAST(`Data17` AS CHAR),'NULL'),COALESCE(CAST(`Data18` AS CHAR),'NULL'),COALESCE(CAST(`Data19` AS CHAR),'NULL'),COALESCE(CAST(`Data20` AS CHAR),'NULL'),COALESCE(CAST(`Data21` AS CHAR),'NULL'),COALESCE(CAST(`Data22` AS CHAR),'NULL'),COALESCE(CAST(`Data23` AS CHAR),'NULL'),COALESCE(CAST(`Data24` AS CHAR),'NULL'),COALESCE(CAST(`Data25` AS CHAR),'NULL'),COALESCE(CAST(`Data26` AS CHAR),'NULL'),COALESCE(CAST(`Data27` AS CHAR),'NULL'),COALESCE(CAST(`Data28` AS CHAR),'NULL'),COALESCE(CAST(`Data29` AS CHAR),'NULL'),COALESCE(CAST(`Data30` AS CHAR),'NULL'),COALESCE(CAST(`Data31` AS CHAR),'NULL'),COALESCE(CAST(`Data32` AS CHAR),'NULL'),COALESCE(CAST(`unkInt32` AS CHAR),'NULL'),COALESCE(CAST(`AIName` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`WorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`StateWorldEffectID` AS CHAR),'NULL'),COALESCE(CAST(`SpellVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateVisualID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimID` AS CHAR),'NULL'),COALESCE(CAST(`SpellStateAnimKitID` AS CHAR),'NULL'),COALESCE(CAST(`MaxVisible` AS CHAR),'NULL'),COALESCE(CAST(`IgnoreDynLos` AS CHAR),'NULL'),COALESCE(CAST(`MinGold` AS CHAR),'NULL'),COALESCE(CAST(`MaxGold` AS CHAR),'NULL'),COALESCE(CAST(`VerifiedBuild` AS CHAR),'NULL')) ORDER BY `entry`,`type`,`displayId`,`name`,`IconName`,`castBarCaption`,`unk1`,`faction`,`flags`,`size`,`questItem1`,`questItem2`,`questItem3`,`questItem4`,`questItem5`,`questItem6`,`Data0`,`Data1`,`Data2`,`Data3`,`Data4`,`Data5`,`Data6`,`Data7`,`Data8`,`Data9`,`Data10`,`Data11`,`Data12`,`Data13`,`Data14`,`Data15`,`Data16`,`Data17`,`Data18`,`Data19`,`Data20`,`Data21`,`Data22`,`Data23`,`Data24`,`Data25`,`Data26`,`Data27`,`Data28`,`Data29`,`Data30`,`Data31`,`Data32`,`unkInt32`,`AIName`,`ScriptName`,`WorldEffectID`,`StateWorldEffectID`,`SpellVisualID`,`SpellStateVisualID`,`SpellStateAnimID`,`SpellStateAnimKitID`,`MaxVisible`,`IgnoreDynLos`,`MinGold`,`MaxGold`,`VerifiedBuild` SEPARATOR '\n'),256) FROM gameobject_template WHERE entry=250386)='a5dc1b9d4ce6e2da188e1b1de1b8c263cc0631df7afa234fb5e1cbce5c8afb3c'
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`Entry` AS CHAR),'NULL'),COALESCE(CAST(`Item` AS CHAR),'NULL'),COALESCE(CAST(`Currency` AS CHAR),'NULL'),COALESCE(CAST(`Reference` AS CHAR),'NULL'),COALESCE(CAST(`Chance` AS CHAR),'NULL'),COALESCE(CAST(`QuestRequired` AS CHAR),'NULL'),COALESCE(CAST(`LootMode` AS CHAR),'NULL'),COALESCE(CAST(`GroupId` AS CHAR),'NULL'),COALESCE(CAST(`MinCount` AS CHAR),'NULL'),COALESCE(CAST(`MaxCount` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `Entry`,`Item`,`Currency`,`Reference`,`Chance`,`QuestRequired`,`LootMode`,`GroupId`,`MinCount`,`MaxCount`,`Comment` SEPARATOR '\n'),256) FROM gameobject_loot_template WHERE Entry=250386)='b250e0db1df64258747304bfb1f45960c389b20d8b7be3a6a803a3add4fcca71'
 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR),'NULL'),COALESCE(CAST(`source_type` AS CHAR),'NULL'),COALESCE(CAST(`id` AS CHAR),'NULL'),COALESCE(CAST(`link` AS CHAR),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR),'NULL'),COALESCE(CAST(`event_type` AS CHAR),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR),'NULL'),COALESCE(CAST(`event_chance` AS CHAR),'NULL'),COALESCE(CAST(`event_flags` AS CHAR),'NULL'),COALESCE(CAST(`event_param1` AS CHAR),'NULL'),COALESCE(CAST(`event_param2` AS CHAR),'NULL'),COALESCE(CAST(`event_param3` AS CHAR),'NULL'),COALESCE(CAST(`event_param4` AS CHAR),'NULL'),COALESCE(CAST(`event_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_type` AS CHAR),'NULL'),COALESCE(CAST(`action_param1` AS CHAR),'NULL'),COALESCE(CAST(`action_param2` AS CHAR),'NULL'),COALESCE(CAST(`action_param3` AS CHAR),'NULL'),COALESCE(CAST(`action_param4` AS CHAR),'NULL'),COALESCE(CAST(`action_param5` AS CHAR),'NULL'),COALESCE(CAST(`action_param6` AS CHAR),'NULL'),COALESCE(CAST(`target_type` AS CHAR),'NULL'),COALESCE(CAST(`target_param1` AS CHAR),'NULL'),COALESCE(CAST(`target_param2` AS CHAR),'NULL'),COALESCE(CAST(`target_param3` AS CHAR),'NULL'),COALESCE(CAST(`target_param4` AS CHAR),'NULL'),COALESCE(CAST(`target_x` AS CHAR),'NULL'),COALESCE(CAST(`target_y` AS CHAR),'NULL'),COALESCE(CAST(`target_z` AS CHAR),'NULL'),COALESCE(CAST(`target_o` AS CHAR),'NULL'),COALESCE(CAST(`comment` AS CHAR),'NULL')) ORDER BY `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment` SEPARATOR '\n'),256) FROM smart_scripts WHERE entryorguid=250386 AND source_type=1)='19894b0932a0145b89ccf649c6a9076bd09ec9fd5f0e442a79eac9ec3db5a776'
 AND ((SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM conditions WHERE (SourceTypeOrReferenceId=4 AND SourceGroup=250386) OR (SourceTypeOrReferenceId=22 AND SourceEntry=250386 AND SourceId=1))='b30d840f368b0f64096e3827b827462d2c10372877338e05957622ff07ea9a23'
 OR (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM conditions WHERE (SourceTypeOrReferenceId=4 AND SourceGroup=250386) OR (SourceTypeOrReferenceId=22 AND SourceEntry=250386 AND SourceId=1))=(SELECT SHA2(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`SourceTypeOrReferenceId` AS CHAR),'NULL'),COALESCE(CAST(`SourceGroup` AS CHAR),'NULL'),COALESCE(CAST(`SourceEntry` AS CHAR),'NULL'),COALESCE(CAST(`SourceId` AS CHAR),'NULL'),COALESCE(CAST(`ElseGroup` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTypeOrReference` AS CHAR),'NULL'),COALESCE(CAST(`ConditionTarget` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue1` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue2` AS CHAR),'NULL'),COALESCE(CAST(`ConditionValue3` AS CHAR),'NULL'),COALESCE(CAST(`NegativeCondition` AS CHAR),'NULL'),COALESCE(CAST(`ErrorTextId` AS CHAR),'NULL'),COALESCE(CAST(`ScriptName` AS CHAR),'NULL'),COALESCE(CAST(`Comment` AS CHAR),'NULL')) ORDER BY `SourceTypeOrReferenceId`,`SourceGroup`,`SourceEntry`,`SourceId`,`ElseGroup`,`ConditionTypeOrReference`,`ConditionTarget`,`ConditionValue1`,`ConditionValue2`,`ConditionValue3`,`NegativeCondition`,`ErrorTextId`,`ScriptName`,`Comment` SEPARATOR '\n'),256) FROM feral_pickup_expected WHERE 1));
SET @feral_check := IF(COALESCE(@feral_safe,0),'DO 0','SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT=''Feral native chest/loot/actions/conditions differ; review before applying''');
PREPARE feral_check FROM @feral_check;EXECUTE feral_check;DEALLOCATE PREPARE feral_check;
UPDATE gameobject_template SET Data1=250386 WHERE @feral_safe AND entry=250386;
DELETE FROM conditions WHERE @feral_safe AND ((SourceTypeOrReferenceId=4 AND SourceGroup=250386) OR (SourceTypeOrReferenceId=22 AND SourceEntry=250386 AND SourceId=1));
INSERT INTO conditions SELECT * FROM feral_pickup_expected WHERE @feral_safe;
COMMIT;
DROP TEMPORARY TABLE feral_pickup_expected;
SET SESSION group_concat_max_len=@feral_concat;
